import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
}

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const date = startOfDay(new Date());
  date.setDate(date.getDate() + days);
  return date;
};

const presets = [
  { key: 'today', label: 'Сегодня', offset: 0 },
  { key: 'yesterday', label: 'Вчера', offset: -1 },
  { key: 'week', label: 'Неделя назад', offset: -7 },
];

const isSameDay = (a: Date | null, b: Date) =>
  a !== null &&
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(defaultValue);
  const date = value !== undefined ? value : internalDate;

  const select = (next: Date | null) => {
    if (value === undefined) setInternalDate(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {presets.map((preset) => {
          const presetDate = shiftDays(preset.offset);
          const active = isSameDay(date, presetDate);
          return (
            <JxChip
              key={preset.key}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              active={active}
              onClick={() => select(presetDate)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  select(presetDate);
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar locale={locale} value={date} onValueChange={select} />

      <p style={{ margin: 0, color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)' }}>
        {date
          ? `Дата отчёта: ${date.toLocaleDateString(locale, { day: 'numeric', month: 'long', year: 'numeric' })}`
          : 'Дата не выбрана — выберите день в календаре или используйте быстрый вариант выше.'}
      </p>
    </div>
  );
}

